      <div
        id="dbg-errs"
        className="absolute bottom-8 left-1/2 -translate-x-1/2 max-w-[600px] break-words bg-black/80 rounded p-6 text-base font-bold pointer-events-none"
      ></div>
    </div>
  );
};

