import { createNoise2D, createNoise3D } from 'simplex-noise';
import { getStructuresForChunk } from './structures.js';
import { BlockIds, BlockById, BlockKeyById } from '../registry/BlockRegistry';
import {
  setBlock,
  getIndex,
  CHUNK_VOLUME,
  CHUNK_Y_MIN,
  CHUNK_Y_MAX,
  CHUNK_HEIGHT,
  CHUNK_PAD,
  HALO_SIZE_X,
  HALO_SIZE_Z,
  CHUNK_SIZE_X,
  CHUNK_SIZE_Z,
