        const islandDetail = islandDetailNoise3D(worldX * 0.02, worldY * 0.02, worldZ * 0.02) * 0.5;
        // Mask to make them rare
        const islandMask = islandBase + islandDetail;
        
        if (islandMask > 0.6) {
           // Use cave noise for inner topology of the island
