      const gz = Math.floor(lz / GRID_STEP);
      const tx = (lx % GRID_STEP) / GRID_STEP;
      const tz = (lz % GRID_STEP) / GRID_STEP;

      for (let y = CHUNK_Y_MIN; y <= CHUNK_Y_MAX; y++) {
