  // Pass 4: Visibility Culling & Output Extraction
  const neighborBlocks = {};
  const buffer = new Uint32Array(CHUNK_VOLUME);

  const isOpaque = (lx, y, lz) => {
    const tex = haloBuffer[getHaloIndex(lx, y, lz)];
