        if (tex === 0) continue;

        if (
          lx === 0 ||
          lx === HALO_SIZE_X - 1 ||
          lz === 0 ||
          lz === HALO_SIZE_Z - 1
        ) {
          const gx = cx * CHUNK_SIZE_X - CHUNK_PAD + lx;
          const gz = cz * CHUNK_SIZE_Z - CHUNK_PAD + lz;
          neighborBlocks[`${gx},${y},${gz}`] = {
            texture: BlockKeyById[tex],
            level: BlockById[tex]?.isLiquid ? 7 : undefined,
