export const setSkipAutoSave = (val) => {
  skipAutoSaveOnExit = val;
};

const visibilityListener = () => {
  if (document.visibilityState === 'hidden' && !skipAutoSaveOnExit) {
    if (window.useStore) {
      const pos = [playerPosition.x, playerPosition.y, playerPosition.z];
      const rot = [
        playerRotation.x,
        playerRotation.y,
        playerRotation.z,
