  // Step 2: Flood Fill Scatter
  while (head < tail) {
    const x = qX[head & QUEUE_MASK];
    const y = qY[head & QUEUE_MASK];
    const z = qZ[head & QUEUE_MASK];
    const val = qV[head & QUEUE_MASK];
    head++;

    if (val <= 1) continue;

    for (let i = 0; i < dirs.length; i++) {
      const dir = dirs[i];
      const nx = x + dir[0];
      const ny = y + dir[1];
      const nz = z + dir[2];

      // Sun scattering only happens at max 14 going sideways/upwards/downwards if obstructed
      const nextVal = val === 15 && dir[1] === -1 ? 15 : val - 1;

      if (ny < CHUNK_Y_MIN || ny > CHUNK_Y_MAX) continue;

      if (
        isTransparent(cx, cz, buffer, neighborBuffers, neighborObj, nx, ny, nz)
      ) {
        const currentLight = getLight(
          cx,
          cz,
          buffer,
          neighborBuffers,
          nx,
          ny,
          nz,
          true
        );
        if (currentLight < nextVal) {
          const success = setLightVal(
            cx,
            cz,
            buffer,
            neighborBuffers,
            nx,
            ny,
            nz,
            nextVal,
            true
          );
          if (success) {
            qX[tail & QUEUE_MASK] = nx;
              qY[tail & QUEUE_MASK] = ny;
              qZ[tail & QUEUE_MASK] = nz;
              qV[tail & QUEUE_MASK] = nextVal;
              tail++;
          } else {
            // Reached an unloaded boundary, emit overflow payload!
            lightOverflow.push({
              x: nx,
              y: ny,
              z: nz,
              val: nextVal,
              type: 'sun',
            });
          }
        }
      }
    }
  }

  return lightOverflow;
};

// --- PASS 2: BLOCK LIGHT BFS ---
export const generateBlockLight = (
  buffer: Uint32Array,
  cx: number,
  cz: number,
  neighborBuffers: NeighborBuffer[] | null | undefined,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  neighborObj: Record<string, any> | null = null
): Array<{x: number, y: number, z: number, val: number, type: string}> => {
  let head = 0;
  let tail = 0;
  const lightOverflow = [];

  // 1. Seed emissive blocks
  for (let i = 0; i < CHUNK_VOLUME; i++) {
    const val = buffer[i];
    if (val === 0) continue;
    const tex = getTextureId(val);
    const lightLvl = BlockById[tex]?.lightLevel || 0;
    if (lightLvl > 0) {
      const lx = i % 16;
      const lz = Math.floor(i / 16) % 16;
      const gy = Math.floor(i / 256) + CHUNK_Y_MIN;
      const gx = cx * 16 + lx;
      const gz = cz * 16 + lz;

      if (
        getLight(cx, cz, buffer, neighborBuffers, gx, gy, gz, false) < lightLvl
      ) {
        setLightVal(
          cx,
          cz,
          buffer,
          neighborBuffers,
          gx,
          gy,
          gz,
          lightLvl,
          false
        );
        qX[tail & QUEUE_MASK] = gx;
          qY[tail & QUEUE_MASK] = gy;
          qZ[tail & QUEUE_MASK] = gz;
          qV[tail & QUEUE_MASK] = lightLvl;
          tail++;
      }
    }
  }

  // 1b: Seed border block light from neighbors
  tail = seedNeighborLight(cx, cz, neighborBuffers, false, tail);

  // 2. Flood Fill
  while (head < tail) {
    const x = qX[head & QUEUE_MASK];
    const y = qY[head & QUEUE_MASK];
    const z = qZ[head & QUEUE_MASK];
    const val = qV[head & QUEUE_MASK];
    head++;

    if (val <= 1) continue;
    const nextVal = val - 1;

    for (let i = 0; i < dirs.length; i++) {
      const nx = x + dirs[i][0];
      const ny = y + dirs[i][1];
      const nz = z + dirs[i][2];

      if (ny < CHUNK_Y_MIN || ny > CHUNK_Y_MAX) continue;

      if (
        isTransparent(cx, cz, buffer, neighborBuffers, neighborObj, nx, ny, nz)
      ) {
        const currentLight = getLight(
          cx,
          cz,
          buffer,
          neighborBuffers,
          nx,
          ny,
          nz,
          false
        );
        if (currentLight < nextVal) {
          const success = setLightVal(
            cx,
            cz,
            buffer,
            neighborBuffers,
            nx,
            ny,
            nz,
            nextVal,
            false
          );
          if (success) {
            qX[tail & QUEUE_MASK] = nx;
              qY[tail & QUEUE_MASK] = ny;
              qZ[tail & QUEUE_MASK] = nz;
              qV[tail & QUEUE_MASK] = nextVal;
              tail++;
          } else {
            lightOverflow.push({
              x: nx,
              y: ny,
              z: nz,
              val: nextVal,
              type: 'block',
            });
          }
        }
      }
    }
  }

  return lightOverflow;
};

// --- PASS 3: LIGHT REMOVAL BFS (GHOST LIGHT FIX) ---
export const removeLight = (
  buffer: Uint32Array,
  cx: number,
  cz: number,
  neighborBuffers: NeighborBuffer[] | null | undefined,
  rx: number,
  ry: number,
  rz: number,
  removedLightVal: number,
  isSunlight: boolean,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  neighborObj: Record<string, any> | null = null
): Array<{x: number, y: number, z: number, val: number, type: string}> => {
  let rHead = 0;
  let rTail = 0;

  let gHead = 0;
  let gTail = 0;

  const lightOverflow = [];

  // Seed removal queue
  rqX[rTail & QUEUE_MASK] = rx;
  rqY[rTail & QUEUE_MASK] = ry;
  rqZ[rTail & QUEUE_MASK] = rz;
  rqV[rTail & QUEUE_MASK] = removedLightVal;
  rTail++;
  setLightVal(cx, cz, buffer, neighborBuffers, rx, ry, rz, 0, isSunlight);

  // 1. Reverse BFS (Darken everything that relied on this light source)
  while (rHead < rTail) {
    const x = rqX[rHead & QUEUE_MASK];
    const y = rqY[rHead & QUEUE_MASK];
    const z = rqZ[rHead & QUEUE_MASK];
    const val = rqV[rHead & QUEUE_MASK];
    rHead++;

    for (let i = 0; i < dirs.length; i++) {
      const nx = x + dirs[i][0];
      const ny = y + dirs[i][1];
      const nz = z + dirs[i][2];

      if (ny < CHUNK_Y_MIN || ny > CHUNK_Y_MAX) continue;

      const neighborLight = getLight(
        cx,
        cz,
        buffer,
        neighborBuffers,
        nx,
        ny,
        nz,
        isSunlight
      );
      if (neighborLight !== 0) {
        // Did the neighbor get its light from us?
        const threshold =
          isSunlight && dirs[i][1] === -1 && val === 15 ? 15 : val - 1;

        if (
          neighborLight === threshold ||
          (isSunlight &&
            dirs[i][1] === -1 &&
            neighborLight === 15 &&
            val === 15)
        ) {
          // Yes! It was relying on us. Darken it and push to removal queue.
          setLightVal(
            cx,
            cz,
            buffer,
            neighborBuffers,
            nx,
            ny,
            nz,
            0,
            isSunlight
          );
          rqX[rTail & QUEUE_MASK] = nx;
            rqY[rTail & QUEUE_MASK] = ny;
            rqZ[rTail & QUEUE_MASK] = nz;
            rqV[rTail & QUEUE_MASK] = neighborLight;
            rTail++;
        } else if (neighborLight >= val) {
          // No! Its light came from somewhere else. Add it to generation queue to re-illuminate!
          qX[gTail & QUEUE_MASK] = nx;
            qY[gTail & QUEUE_MASK] = ny;
            qZ[gTail & QUEUE_MASK] = nz;
            qV[gTail & QUEUE_MASK] = neighborLight;
            gTail++;
        }
      }
    }
  }

  // 2. Standard BFS (Re-illuminate from other sources)
  while (gHead < gTail) {
    const x = qX[gHead & QUEUE_MASK];
    const y = qY[gHead & QUEUE_MASK];
    const z = qZ[gHead & QUEUE_MASK];
    const val = qV[gHead & QUEUE_MASK];
    gHead++;

    if (val <= 1) continue;

    for (let i = 0; i < dirs.length; i++) {
      const nx = x + dirs[i][0];
      const ny = y + dirs[i][1];
      const nz = z + dirs[i][2];

      if (ny < CHUNK_Y_MIN || ny > CHUNK_Y_MAX) continue;

      const nextVal =
        isSunlight && val === 15 && dirs[i][1] === -1 ? 15 : val - 1;

      if (
        isTransparent(cx, cz, buffer, neighborBuffers, neighborObj, nx, ny, nz)
      ) {
        const currentLight = getLight(
          cx,
          cz,
          buffer,
          neighborBuffers,
          nx,
          ny,
          nz,
          isSunlight
        );
        if (currentLight < nextVal) {
          const success = setLightVal(
            cx,
            cz,
            buffer,
            neighborBuffers,
            nx,
            ny,
            nz,
            nextVal,
            isSunlight
          );
          if (success) {
            qX[gTail & QUEUE_MASK] = nx;
              qY[gTail & QUEUE_MASK] = ny;
              qZ[gTail & QUEUE_MASK] = nz;
              qV[gTail & QUEUE_MASK] = nextVal;
              gTail++;
          } else {
            lightOverflow.push({
              x: nx,
              y: ny,
              z: nz,
              val: nextVal,
              type: isSunlight ? 'sun' : 'block',
            });
          }
        }
      }
    }
  }

  return lightOverflow;
};

import ChunkWorkerClass from '../workers/chunkWorker?worker';
import { useChunkStore } from '../stores/chunkSlice';
import { getBinaryRegistries } from '../registry/BlockRegistry';
import type { ChunkWorkerRequest, ChunkWorkerResponse } from '../types/workers';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
let getPass1Cache: (() => Map<string, any>) | null = null;
const POOL_SIZE = Math.min(
  Math.max(Math.floor((navigator.hardwareConcurrency || 2) / 2), 1),
  4
);

export interface WorkerObj {
  instance: Worker;
  lastPingTime: number;
  isBusy: boolean;
  isDead: boolean;
  index: number;
  activeChunkKey?: string | null;
  startTime?: number;
}

export interface WorkerTask {
  type: string;
  cx?: number;
  cz?: number;
  seed?: number;
  buffer?: Uint32Array | ArrayBuffer;
  getSurfaceHeightMap?: Int16Array;
  packedBuffer?: Uint32Array;
  neighborBuffers?: Array<{cx: number, cz: number, buffer: Uint32Array}>;
  removedLights?: unknown[];
  isHighPriority?: boolean;
  resolve: (value: unknown) => void;
}

class WorkerManager {
  _idle: WorkerObj[];
  _pending: Map<WorkerObj, (value: unknown) => void>;
  _queue: WorkerTask[];
  workers: WorkerObj[];
  pingPongPool: ArrayBuffer[];
  activeChunks: Set<string>;
  cancelledInFlight: Set<string>;
  _ingestionQueue: Array<() => void>;
  _ingestionRunning: boolean;
  watchdogInterval?: ReturnType<typeof setInterval>;

  constructor() {
    this._idle = []; // workerObjs waiting for a job
    this._pending = new Map(); // workerObj → resolve fn
    this._queue = []; // waiting jobs
    this.workers = [];
    this.pingPongPool = [];
    this.activeChunks = new Set(); // Prevent chunk data race conditions
    this.cancelledInFlight = new Set();
    this._ingestionQueue = [];
    this._ingestionRunning = false;

    for (let i = 0; i < POOL_SIZE; i++) {
      this.spawnWorker(i);
    }

    if (import.meta.env.DEV) {
      console.log(
        `[WorkerManager] ${POOL_SIZE} workers ready (${navigator.hardwareConcurrency} logical cores)`
      );
    }

    this.watchdogInterval = setInterval(() => this.watchdogCheck(), 2000);

    // Global telemetry for the Debug Overlay
    window.__workerTelemetry = {
      resets: 0,
      activeJobs: 0,
      poolSize: POOL_SIZE,
      queueLength: 0,
      latencies: [],
      avgLatency: 0,
    };
  }

  _processIngestionQueue() {
    if (this._ingestionQueue.length === 0) {
      this._ingestionRunning = false;
      return;
    }
    
    // Resolve 1 chunk per frame to protect GPU budget
    const task = this._ingestionQueue.shift();
    task(); 
    
    requestAnimationFrame(() => this._processIngestionQueue());
  }

  spawnWorker(index: number) {
    const worker = new ChunkWorkerClass();
    const workerObj = {
      instance: worker,
      lastPingTime: Date.now(),
      isBusy: false,
      isDead: false,
      index: index,
    };
    this.workers[index] = workerObj;

    worker.onmessage = ({ data }: MessageEvent<ChunkWorkerResponse>) => this._onResult(workerObj, data);
    worker.onerror = (e) => this._onError(workerObj, e);

    const registries = getBinaryRegistries();
    const solidBuf = registries.solidBuffer.slice(0);
    const fluidBuf = registries.fluidBuffer.slice(0);
    const texBuf = registries.textureBuffer.slice(0);
    const floraBuf = registries.floraBuffer.slice(0);
    const transBuf = registries.transparentBuffer.slice(0);
    
    worker.postMessage({
      type: 'INIT_REGISTRY',
      solidBuffer: solidBuf,
      fluidBuffer: fluidBuf,
      textureBuffer: texBuf,
      floraBuffer: floraBuf,
      transparentBuffer: transBuf
    }, [solidBuf, fluidBuf, texBuf, floraBuf, transBuf]);

    this._idle.push(workerObj);
  }

  generatePass1(cx: number, cz: number, seed: number) {
    return new Promise((resolve) => {
      this._queue.push({ type: 'generatePass1', cx, cz, seed, resolve });
      this.processNextJob();
    });
  }

  generatePass2(cx: number, cz: number, buffer: ArrayBuffer, getSurfaceHeightMap: Int16Array, seed: number) {
    return new Promise((resolve) => {
      const firstPass1Idx = this._queue.findIndex((t) => t.type === 'generatePass1');
      const task = {
        type: 'generatePass2',
        cx,
        cz,
        buffer,
        getSurfaceHeightMap,
        seed,
        resolve,
      };
      if (firstPass1Idx !== -1) {
        this._queue.splice(firstPass1Idx, 0, task);
      } else {
        this._queue.push(task);
      }
      this.processNextJob();
    });
  }

  cancelGenerate(cx: number, cz: number) {
    const key = `${cx},${cz}`;
    if (this.activeChunks.has(key)) {
      this.cancelledInFlight.add(key);
    }
    const idx1 = this._queue.findIndex(
      (t) => t.type === 'generatePass1' && t.cx === cx && t.cz === cz
    );
    if (idx1 !== -1) {
      const task = this._queue.splice(idx1, 1)[0];
      task.resolve({ error: 'CANCELLED' });
    }
    const idx2 = this._queue.findIndex(
      (t) => t.type === 'generatePass2' && t.cx === cx && t.cz === cz
    );
    if (idx2 !== -1) {
      const task = this._queue.splice(idx2, 1)[0];
      task.resolve({ error: 'CANCELLED' });
    }
  }

  cancelRebuild(cx: number, cz: number) {
    const key = `${cx},${cz}`;
    if (this.activeChunks.has(key)) {
      this.cancelledInFlight.add(key);
    }
    this._queue = this._queue.filter((t) => {
      if (t.type === 'rebuild' && t.cx === cx && t.cz === cz) {
        t.resolve({ error: 'CANCELLED' });
        return false;
      }
      return true;
    });
  }

  cancelAllPending() {
    for (const key of this.activeChunks) {
      this.cancelledInFlight.add(key);
    }
    this._queue.forEach(t => t.resolve({ error: 'CANCELLED' }));
    this._queue = [];
    for (const resolve of this._pending.values()) {
      resolve({ error: 'CANCELLED' });
    }
    this._pending.clear();
    if (window.__workerTelemetry) {
      window.__workerTelemetry.activeJobs = 0;
      window.__workerTelemetry.queueLength = 0;
    }
  }

  rebuild(packedBuffer: Uint32Array, neighborBuffers: Array<{cx: number, cz: number, buffer: Uint32Array}>, cx: number, cz: number, seed: number, removedLights?: unknown[], isHighPriority = false) {
    return new Promise((resolve) => {
      const firstGenIdx = this._queue.findIndex(
        (t) => t.type === 'generatePass1' || t.type === 'generatePass2'
      );
      const task = {
        type: 'rebuild',
        cx,
        cz,
        packedBuffer,
        neighborBuffers,
        resolve,
        removedLights,
        isHighPriority
      };

      if (isHighPriority && firstGenIdx !== -1) {
        this._queue.splice(firstGenIdx, 0, task);
      } else {
        this._queue.push(task);
      }
      this.processNextJob();
    });
  }

  recycleBuffers(toRecycle: ArrayBuffer[]) {
    if (!toRecycle || toRecycle.length === 0) return;
    const batches = Array.from({ length: POOL_SIZE }, () => []);
    toRecycle.forEach((buf, i) => {
      if (buf.byteLength === 294912 || buf.byteLength === 262144) {
        if (this.pingPongPool.length < 50) this.pingPongPool.push(buf);
      } else {
        batches[i % POOL_SIZE].push(buf);
      }
    });
    batches.forEach((batch, i) => {
        if (batch.length > 0) {
            const workerObj = this.workers[i];
            if (workerObj && !workerObj.isDead) {
                const MAX_TRANSFER = 50;
                for (let k = 0; k < batch.length; k += MAX_TRANSFER) {
                    const subBatch = batch.slice(k, k + MAX_TRANSFER);
                    try {
                        workerObj.instance.postMessage({ type: 'RECYCLE', buffers: subBatch }, subBatch);
                    } catch(_e) {}
                }
            }
        }
    });
  }

  watchdogCheck() {
    const NOW = Date.now();
    const TIMEOUT_LIMIT = 30000;

    this.workers.forEach((workerObj, index) => {
      if (workerObj.isBusy && NOW - workerObj.lastPingTime > TIMEOUT_LIMIT) {
        console.warn(
          `[WorkerManager] Worker ${index} froze or crashed silently! Terminating and resetting...`
        );

        try {
          workerObj.instance.terminate();
        } catch {}
        workerObj.isDead = true;
        window.__workerTelemetry.resets++;

        if (workerObj.activeChunkKey) {
            this.activeChunks.delete(workerObj.activeChunkKey);
            workerObj.activeChunkKey = null;
        }

        const resolve = this._pending.get(workerObj);
        if (resolve) resolve({ error: 'WORKER_TIMEOUT' });
        this._pending.delete(workerObj);
        window.__workerTelemetry.activeJobs = this._pending.size;

        this._idle = this._idle.filter((w) => w !== workerObj);
        this.spawnWorker(index);
        this.processNextJob();
      } else if (!workerObj.isDead) {
        workerObj.instance.postMessage({ type: 'PING' });
      }
    });
  }

  processNextJob() {
    window.__workerTelemetry.queueLength = this._queue.length;
    if (this._queue.length > 0) {
      if (this._idle.length > 0) {
        // Find the first task whose chunk isn't actively being processed by another worker
        let taskIdx = this._queue.findIndex((t) => !this.activeChunks.has(`${t.cx},${t.cz}`));
        
        if (taskIdx !== -1) {
          const taskObjCheck = this._queue[taskIdx];
          // Reserve the last idle worker for fast tasks (like block breaking).
          if (this._idle.length === 1 && POOL_SIZE > 1 && (taskObjCheck.type === 'generatePass1' || taskObjCheck.type === 'generatePass2')) {
            const rebuildIdx = this._queue.findIndex(t => t.type === 'rebuild' && !this.activeChunks.has(`${t.cx},${t.cz}`));
            if (rebuildIdx !== -1) {
              taskIdx = rebuildIdx;
            } else {
              return;
            }
          }

          const workerObj = this._idle.pop();
          const task = this._queue.splice(taskIdx, 1)[0];
          this.activeChunks.add(`${task.cx},${task.cz}`);
          
          if (task.type === 'generatePass1') {
            this._dispatchGeneratePass1(
              workerObj,
              task.cx,
              task.cz,
              task.seed,
              task.resolve
            );
          } else if (task.type === 'generatePass2') {
            this._dispatchGeneratePass2(
              workerObj,
              task.cx,
              task.cz,
              task.buffer,
              task.getSurfaceHeightMap,
              task.seed,
              task.resolve
            );
          } else if (task.type === 'rebuild') {
            this._dispatchRebuild(
              workerObj,
              task.cx,
              task.cz,
              task.packedBuffer,
              task.neighborBuffers,
              task.resolve,
              task.removedLights
            );
          }
        }
      }
    }
  }

  _dispatchGeneratePass1(workerObj: WorkerObj, cx: number, cz: number, seed: number, resolve: (v: unknown) => void) {
    workerObj.isBusy = true;
    workerObj.activeChunkKey = `${cx},${cz}`;
    workerObj.lastPingTime = Date.now();
    workerObj.startTime = performance.now();
    this._pending.set(workerObj, resolve);
    window.__workerTelemetry.activeJobs = this._pending.size;
    workerObj.instance.postMessage({ type: 'generatePass1', cx, cz, seed });
  }

  _dispatchGeneratePass2(
    workerObj: WorkerObj,
    cx: number,
    cz: number,
    buffer: ArrayBuffer | Uint32Array,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    getSurfaceHeightMap: Int16Array | any,
    seed: number,
    resolve: (v: unknown) => void
  ) {
    workerObj.isBusy = true;
    workerObj.activeChunkKey = `${cx},${cz}`;
    workerObj.lastPingTime = Date.now();
    workerObj.startTime = performance.now();
    this._pending.set(workerObj, resolve);
    window.__workerTelemetry.activeJobs = this._pending.size;

    try {
      // Gather neighbor buffers for mesh building step!
      // Use injected getPass1Cache to avoid circular dependency
      const chunkStore = useChunkStore.getState();
      const neighborBuffers = [];
      const pass1Cache = getPass1Cache ? getPass1Cache() : null;

      for (let nx = -1; nx <= 1; nx++) {
        for (let nz = -1; nz <= 1; nz++) {
          if (nx === 0 && nz === 0) continue;
          const key = `${cx + nx},${cz + nz}`;
          let nBuffer = null;

          if (chunkStore.chunks[key] && chunkStore.chunks[key].buffer) {
            nBuffer = chunkStore.chunks[key].buffer;
          } else if (pass1Cache && pass1Cache.has(key)) {
            nBuffer = pass1Cache.get(key).buffer;
          }

          if (nBuffer) {
            neighborBuffers.push({ cx: cx + nx, cz: cz + nz, buffer: nBuffer });
          }
        }
      }

      // Guard: buffer and getSurfaceHeightMap must be live (non-null, non-detached) TypedArrays.
      // If a chunk was evicted by NO_DATA and re-queued, the original pass1Data TypedArrays may be
      // detached (byteLength === 0) because their underlying ArrayBuffers were previously transferred.
      // Sending a detached or null buffer to the worker causes "Cannot convert null object" in
      // `new Float32Array(getSurfaceHeightMap)` inside chunkWorker.js.
      if (!buffer || !buffer.buffer || buffer.buffer.byteLength === 0) {
        console.warn(`[WorkerManager] Pass2 dispatch aborted for ${cx},${cz}: packedBuffer is null or detached.`);
        this._pending.delete(workerObj);
        workerObj.isBusy = false;
        resolve({ error: 'DETACHED_BUFFER' });
        this._idle.push(workerObj);
        this.processNextJob();
        return;
      }
      if (!getSurfaceHeightMap || !getSurfaceHeightMap.buffer || getSurfaceHeightMap.buffer.byteLength === 0) {
        console.warn(`[WorkerManager] Pass2 dispatch aborted for ${cx},${cz}: heightMap is null or detached.`);
        this._pending.delete(workerObj);
        workerObj.isBusy = false;
        resolve({ error: 'DETACHED_BUFFER' });
        this._idle.push(workerObj);
        this.processNextJob();
        return;
      }

      // Implement Input Ping-Pong Pool to eliminate 2.8MB GC Spikes!
      const transfers = new Set();
      
      let pBuf = this.pingPongPool.pop();
      if (!pBuf || pBuf.byteLength !== buffer.byteLength) pBuf = new ArrayBuffer(buffer.byteLength);
      const sourceArray = buffer instanceof Uint32Array ? buffer : new Uint32Array(buffer);
      new Uint32Array(pBuf).set(sourceArray);
      transfers.add(pBuf);

      const safeNeighborBuffers = neighborBuffers.map(n => {
         if (!n.buffer || n.buffer.byteLength === 0) return { cx: n.cx, cz: n.cz, buffer: new Uint32Array(0) };
         let nBuf = this.pingPongPool.pop();
         if (!nBuf || nBuf.byteLength !== n.buffer.byteLength) nBuf = new ArrayBuffer(n.buffer.byteLength);
         const sourceArray = n.buffer instanceof Uint32Array ? n.buffer : new Uint32Array(n.buffer);
         new Uint32Array(nBuf).set(sourceArray);
         transfers.add(nBuf);
         return { cx: n.cx, cz: n.cz, buffer: new Uint32Array(nBuf) };
      });

      workerObj.instance.postMessage(
        {
          type: 'generatePass2',
          cx,
          cz,
          buffer: pBuf,
          getSurfaceHeightMap: getSurfaceHeightMap.buffer,
          seed,
          neighborBuffers: safeNeighborBuffers,
        },
        Array.from(transfers)
      );
    } catch (e) {
      console.error('[WorkerManager] Generate postMessage failed:', e);
      this._pending.delete(workerObj);
      workerObj.isBusy = false;
      resolve({ error: 'POST_MESSAGE_FAILED' });
      this._idle.push(workerObj);
      this.processNextJob();
    }
  }

  _dispatchRebuild(
    workerObj: WorkerObj,
    cx: number,
    cz: number,
    packedBuffer: Uint32Array,
    neighborBuffers: Array<{cx: number, cz: number, buffer: Uint32Array}>,
    resolve: (v: unknown) => void,
    removedLights?: unknown[]
  ) {
    workerObj.isBusy = true;
    workerObj.activeChunkKey = `${cx},${cz}`;
    workerObj.lastPingTime = Date.now();
    workerObj.startTime = performance.now();
    this._pending.set(workerObj, resolve);
    window.__workerTelemetry.activeJobs = this._pending.size;

    const uniqueTransfers = new Set();

    // Also ensure packedBuffer and neighborBuffers aren't detached!
    if (packedBuffer && packedBuffer.byteLength === 0) {
      console.error('[WorkerManager] packedBuffer is detached!');
      resolve({ error: 'DETACHED_BUFFER' });
      this._idle.push(workerObj);
      this._pending.delete(workerObj);
      workerObj.isBusy = false;
      this.processNextJob();
      return;
    }

    try {
      let safePackedBuffer = packedBuffer;
      if (packedBuffer && packedBuffer.byteLength > 0) {
         let pBuf = this.pingPongPool.pop();
         if (!pBuf || pBuf.byteLength !== packedBuffer.byteLength) pBuf = new ArrayBuffer(packedBuffer.byteLength);
         const sourceArray = packedBuffer instanceof Uint32Array ? packedBuffer : new Uint32Array(packedBuffer);
         new Uint32Array(pBuf).set(sourceArray);
         uniqueTransfers.add(pBuf);
         safePackedBuffer = new Uint32Array(pBuf);
      }

      const safeNeighborBuffers = neighborBuffers ? neighborBuffers.map(n => {
         if (!n.buffer || n.buffer.byteLength === 0) return { cx: n.cx, cz: n.cz, buffer: new Uint32Array(0) };
         let nBuf = this.pingPongPool.pop();
         if (!nBuf || nBuf.byteLength !== n.buffer.byteLength) nBuf = new ArrayBuffer(n.buffer.byteLength);
         const sourceArray = n.buffer instanceof Uint32Array ? n.buffer : new Uint32Array(n.buffer);
         new Uint32Array(nBuf).set(sourceArray);
         uniqueTransfers.add(nBuf);
         return { cx: n.cx, cz: n.cz, buffer: new Uint32Array(nBuf) };
      }) : [];

      workerObj.instance.postMessage(
        {
          type: 'rebuild',
          cx,
          cz,
          packedBuffer: safePackedBuffer,
          neighborBuffers: safeNeighborBuffers,
          removedLights,
        },
        Array.from(uniqueTransfers)
      );
    } catch (e) {
      console.error('[WorkerManager] Rebuild postMessage failed:', e);
      this._pending.delete(workerObj);
      workerObj.isBusy = false;
      resolve(new Error('POST_MESSAGE_FAILED'));
      this._idle.push(workerObj);
      this.processNextJob();
    }
  }

  _onResult(workerObj: WorkerObj, data: ChunkWorkerResponse) {
    if (data.type === 'PONG') {
      workerObj.lastPingTime = Date.now();
      return;
    }

    workerObj.isBusy = false;
    if (workerObj.activeChunkKey) {
        this.activeChunks.delete(workerObj.activeChunkKey);
        workerObj.activeChunkKey = null;
    }

    if (workerObj.startTime) {
      const ms = performance.now() - workerObj.startTime;
      const t = window.__workerTelemetry;
      t.latencies.push(ms);
      if (t.latencies.length > 50) t.latencies.shift();
      t.avgLatency = Math.round(
        t.latencies.reduce((a, b) => a + b, 0) / t.latencies.length
      );
      workerObj.startTime = 0;
    }

    const resolve = this._pending.get(workerObj);
    if (resolve) {
      this._pending.delete(workerObj);
      window.__workerTelemetry.activeJobs = this._pending.size;

      if (data.recycledBuffers) {
        for (const rb of data.recycledBuffers) {
           if (rb && rb.byteLength > 0 && this.pingPongPool.length < 50) {
             this.pingPongPool.push(rb);
           }
        }
      }

      if (data.type === 'CORRUPTED_SAVE') {
        resolve({ error: 'CORRUPTED_SAVE', chunkKey: data.chunkKey });
      } else if (data.type === 'error') {
        resolve({ error: data.message });
      } else if (data.type === 'generatePass1') {
        resolve(data.chunkData);
      } else {
        const chunkKey = `${data.cx},${data.cz}`;
        this._ingestionQueue.push(() => {
          if (this.cancelledInFlight.has(chunkKey)) {
             this.cancelledInFlight.delete(chunkKey);
             if (data.buffer && (data.buffer.byteLength === 294912 || data.buffer.byteLength === 262144)) {
                 if (this.pingPongPool.length < 50) this.pingPongPool.push(data.buffer);
             } else if (data.buffer) {
                 this.recycleBuffers([data.buffer]);
             }
             if (data.meshArrays) {
                 const toRecycle = [];
                 for (const val of Object.values(data.meshArrays)) {
                     if (val instanceof Float32Array || val instanceof Uint32Array) {
                         toRecycle.push(val.buffer);
                     }
                 }
                 this.recycleBuffers(toRecycle);
             }
             resolve({ error: 'CANCELLED_IN_FLIGHT' });
             return;
          }
          if (data.type === 'generatePass2') {
            resolve(data);
          } else if (data.type === 'rebuild') {
            resolve({ meshArrays: data.meshArrays, lightOverflow: data.lightOverflow, buffer: data.buffer });
          } else {
            resolve({ error: 'UNKNOWN_PAYLOAD' });
          }
        });

        if (!this._ingestionRunning) {
          this._ingestionRunning = true;
          requestAnimationFrame(() => this._processIngestionQueue());
        }
      }
    }

    this._idle.push(workerObj);
    this.processNextJob();
  }

  _onError(workerObj: WorkerObj, e: unknown) {
    console.error('[WorkerManager] worker error:', e?.message || e);
    workerObj.isBusy = false;
    if (workerObj.activeChunkKey) {
        this.activeChunks.delete(workerObj.activeChunkKey);
        workerObj.activeChunkKey = null;
    }

    const resolve = this._pending.get(workerObj);
    if (resolve) resolve({ error: 'WORKER_FATAL_ERROR' });
    this._pending.delete(workerObj);
    window.__workerTelemetry.activeJobs = this._pending.size;

    try {
      workerObj.instance.terminate();
    } catch {}
    workerObj.isDead = true;
    window.__workerTelemetry.resets++;

    this._idle = this._idle.filter((w) => w !== workerObj);
    this.spawnWorker(workerObj.index);
    this.processNextJob();
  }

  terminateAll() {
    clearInterval(this.watchdogInterval);
    for (const w of this.workers) {
      if (w && w.instance) {
        try {
          w.instance.terminate();
        } catch {}
      }
    }
    this._idle = [];
    for (const resolve of this._pending.values()) {
      resolve({ error: 'WORKER_TERMINATED' });
    }
    this._pending.clear();
  }
}

// Singleton — one pool for the whole app
export const chunkWorkerPool = new WorkerManager();

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const injectWorkerDependencies = (pass1CacheGetter: () => Map<string, any>) => {
    getPass1Cache = pass1CacheGetter;
};

// Fix: Prevent massive Web Worker memory leak on Vite HMR
if (import.meta.hot) {
  import.meta.hot.dispose(() => {
    chunkWorkerPool.terminateAll();
  });
}

/**
 * chunkWorker.js — Off-thread chunk generation + greedy mesh worker.
 *
 * WHY A WORKER:
 * generateChunk() runs ~50,000 simplex noise samples + visibility culls + greedy
 * mesh computation per chunk. Running this on the main thread blocks React's
 * render loop → the game visibly freezes every time a new chunk is needed.
 *
 * This worker runs everything on a separate OS thread. The main thread stays
 * at 60 fps during chunk loading — no freezes, no latency spikes.
 *
 * TRANSFERABLE ARRAYBUFFERS:
 * The mesh geometry arrays (pos/norm/idx Float32Array / Uint32Array) can be
 * transferred to the main thread via postMessage transferables rather than
 * structured-cloned (copied). Transferring is O(1) — the ArrayBuffer ownership
 * moves instantly with no data duplication regardless of geometry size.
 * After transfer, the worker's typed arrays become detached (zero bytes) and
 * eligible for GC — no memory leak on the worker side.
 */

import {
  generateChunkPass1,
  generateChunkPass2,
} from '../utils/chunkGenerator.js';
import type { ChunkWorkerRequest, ChunkWorkerResponse } from '../types/workers';
import { CHUNK_VOLUME, getIndex } from '../utils/chunkData.js';
import { buildGreedyArrays } from '../utils/greedyMesh.js';
import {
  generateSunlight,
  generateBlockLight,
  removeLight,
} from '../utils/lighting.js';


const recycledBufferBuckets = {};
for (let i = 8; i <= 24; i++) recycledBufferBuckets[1 << i] = [];
  const getBucket = (size) => {
    let pow = 1;
    while (pow * 2 <= size) pow *= 2;
    return pow;
  };
const MAX_POOL_SIZE = 1500;

let SolidLookup = null;
let FluidLookup = null;
let TextureLookup = null;
let FloraLookup = null;
let TransparentLookup = null;
let isReady = false;

  const computeHeightmap = (buffer) => {
    const heightmap = new Float32Array(256);
    let hIdx = 0;
    for (let lz = 0; lz < 16; lz++) {
      for (let lx = 0; lx < 16; lx++) {
        let highest = -999;
        let idx = getIndex(lx, 255, lz);
        
        for (let y = 255; y >= -32; y--) {
          const tex = buffer[idx] & 0xFF;
          if (tex !== 0 && SolidLookup[tex] === 1) {
            highest = y;
            break;
          }
          idx -= 256;
        }
        heightmap[hIdx++] = highest;
      }
    }
    return heightmap;
  };

const extractTransfers = (meshArrays) => {
  const uniqueTransfers = new Set();

  if (meshArrays) {
    if (meshArrays.__flora?.matrices?.buffer?.byteLength > 0) {
      uniqueTransfers.add(meshArrays.__flora.matrices.buffer);
    }
    if (meshArrays.__flora?.packed?.buffer?.byteLength > 0) {
      uniqueTransfers.add(meshArrays.__flora.packed.buffer);
    }
    if (meshArrays.__meta?.heightmap?.buffer?.byteLength > 0) {
      uniqueTransfers.add(meshArrays.__meta.heightmap.buffer);
    }

    for (const [key, arrays] of Object.entries(meshArrays)) {
      if (key === '__meta' || key === '__flora') continue;
      if (Array.isArray(arrays)) {
        for (const part of arrays) {
          if (part.pos?.buffer?.byteLength > 0) uniqueTransfers.add(part.pos.buffer);
          if (part.norm?.buffer?.byteLength > 0) uniqueTransfers.add(part.norm.buffer);
          if (part.color?.buffer?.byteLength > 0) uniqueTransfers.add(part.color.buffer);
          if (part.uv?.buffer?.byteLength > 0) uniqueTransfers.add(part.uv.buffer);
          if (part.idx?.buffer?.byteLength > 0) uniqueTransfers.add(part.idx.buffer);
        }
      }
    }
  }

  return { transferables: Array.from(uniqueTransfers) };
};

self.onmessage = async (e: MessageEvent<ChunkWorkerRequest>) => {
  const data = e.data;
  if (data.type === 'INIT_REGISTRY') {
    SolidLookup = new Uint8Array(data.solidBuffer);
    FluidLookup = new Uint8Array(data.fluidBuffer);
    TextureLookup = new Uint16Array(data.textureBuffer);
    FloraLookup = new Uint8Array(data.floraBuffer);
    TransparentLookup = new Uint8Array(data.transparentBuffer);
    isReady = true;
    return;
  }

  if (data.type === 'PING') {
    self.postMessage({ type: 'PONG' });
    return;
  }
  
  if (data.type === 'RECYCLE') {
    if (data.buffers) {
      let currentSize = 0;
      for (const key in recycledBufferBuckets) currentSize += recycledBufferBuckets[key].length;
      
      for (let i = 0; i < data.buffers.length; i++) {
        if (currentSize >= MAX_POOL_SIZE) break; 
        const buf = data.buffers[i];
        const bucketSize = getBucket(buf.byteLength);
        if (recycledBufferBuckets[bucketSize]) {
           recycledBufferBuckets[bucketSize].push(buf);
           currentSize++;
        }
      }
    }
    return;
  }

  if (!isReady) {
    self.postMessage({
      type: 'error',
      message: 'Worker received generation task before registry initialization.',
      cx: (data as any)?.cx,
      cz: (data as any)?.cz,
    });
    return;
  }

  try {
    if (data.type === 'generatePass1') {
      const { cx, cz, seed } = data;
      const pass1Data = generateChunkPass1(cx, cz, seed);

      // Pass 1 just returns the buffer and neighborBlocks, NO MESHES YET
      self.postMessage(
        { type: 'generatePass1', cx, cz, chunkData: pass1Data },
        [pass1Data.buffer.buffer]
      );
    } else if (data.type === 'generatePass2') {
      const { cx, cz, buffer, getSurfaceHeightMap, seed } = data;

      // We must reconstruct the Int16Array from the raw ArrayBuffer passed to the worker
      const heightMap = new Int16Array(getSurfaceHeightMap);
      const packedBuffer = new Uint32Array(buffer);

      const { buffer: newBuffer, overflow } = generateChunkPass2(
        cx,
        cz,
        packedBuffer,
        heightMap,
        seed
      );

      // After Pass 2, we can finally generate the LightMap and Greedy Mesh!
      // In Pass 2, we don't have neighbor buffers yet... wait!
      // The worker needs neighbor buffers for lighting, just like rebuild mode.
      const neighborBuffers = data.neighborBuffers || [];
      const sunOverflow = generateSunlight(newBuffer, cx, cz, neighborBuffers);
      const blockOverflow = generateBlockLight(
        newBuffer,
        cx,
        cz,
        neighborBuffers
      );
      const lightOverflow = [...sunOverflow, ...blockOverflow];

      const meshArrays = buildGreedyArrays(newBuffer, cx, cz, neighborBuffers, recycledBufferBuckets, SolidLookup, FluidLookup, TextureLookup, FloraLookup, TransparentLookup);
      if (!meshArrays.__meta) meshArrays.__meta = {};
      meshArrays.__meta.heightmap = computeHeightmap(newBuffer);

      const { transferables } = extractTransfers(meshArrays);
      const transferSet = new Set(transferables);
      transferSet.add(newBuffer.buffer); // Pass the final modified Uint32Array back!

      const recycledBuffers = [];
      if (data.neighborBuffers) {
        for (const nb of data.neighborBuffers) {
          if (nb.buffer) {
             const ab = nb.buffer.buffer || nb.buffer;
             recycledBuffers.push(ab);
             transferSet.add(ab);
          }
        }
      }

      self.postMessage(
        {
          type: 'generatePass2',
          cx,
          cz,
          buffer: newBuffer.buffer,
          overflow,
          lightOverflow,
          meshArrays,
          recycledBuffers
        },
        Array.from(transferSet)
      );
    } else if (data.type === 'rebuild') {
      // FAILSAFE 1: Strict Runtime Payload Assertion
      if (data.neighborBuffers && !Array.isArray(data.neighborBuffers)) {
        throw new TypeError(
          `[CRITICAL WORKER FAILSAFE] Expected data.neighborBuffers to be an Array, received: ${typeof data.neighborBuffers}`
        );
      }

      const buffer = data.packedBuffer; // Uint32Array

      // In rebuild mode, neighborBuffers is an array of objects: { cx, cz, buffer }
      const neighborBuffers = data.neighborBuffers || [];

      let cx = data.cx;
      let cz = data.cz;

      // FIX Ghost Lights: Use specifically passed removed lights (from block destruction)
      const removedLightOverflow = [];
      if (data.removedLights && data.removedLights.length > 0) {
        for (const l of data.removedLights) {
          const isSun = l.type === 'sun';
          removedLightOverflow.push(...removeLight(buffer, cx, cz, neighborBuffers, l.x, l.y, l.z, l.val, isSun));
        }
      }

      // Clear existing light in the buffer
      // Bits 22-25: Block Light, Bits 26-29: Sun Light.
      // Mask ~0x3FC00000 clears these bits so the chunk regenerates light purely from scratch.
      for (let i = 0; i < CHUNK_VOLUME; i++) {
        buffer[i] &= ~0x3fc00000;
      }

      // Generate light map seeded from BOTH internal blocks and neighbor buffers
      const sunOverflow = generateSunlight(buffer, cx, cz, neighborBuffers);
      const blockOverflow = generateBlockLight(buffer, cx, cz, neighborBuffers);
      const lightOverflow = [...removedLightOverflow, ...sunOverflow, ...blockOverflow];
      const meshArrays = buildGreedyArrays(buffer, cx, cz, neighborBuffers, recycledBufferBuckets, SolidLookup, FluidLookup, TextureLookup, FloraLookup, TransparentLookup);
      if (!meshArrays.__meta) meshArrays.__meta = {};
      meshArrays.__meta.heightmap = computeHeightmap(buffer);

      const { transferables } = extractTransfers(meshArrays);
      const transferSet = new Set(transferables);
      transferSet.add(buffer.buffer);

      const recycledBuffers = [];
      if (data.neighborBuffers) {
        for (const nb of data.neighborBuffers) {
          if (nb.buffer) {
             const ab = nb.buffer.buffer || nb.buffer;
             recycledBuffers.push(ab);
             transferSet.add(ab);
          }
        }
      }

      self.postMessage(
        { type: 'rebuild', cx, cz, meshArrays, lightOverflow, buffer: buffer.buffer, recycledBuffers },
        Array.from(transferSet)
      );
    }
  } catch (_err) {
    console.error(
      `[ChunkWorker] Fatal Error in Worker Thread for chunk ${data?.cx},${data?.cz}:`,
      _err
    );
    self.postMessage({
      type: 'error',
      message: _err.message,
      stack: _err.stack,
      cx: (data as any)?.cx,
      cz: (data as any)?.cz,
    });
  }
};

// @ts-nocheck
import { get, del, setMany, keys } from 'idb-keyval';
import { BlockIds } from '../registry/BlockRegistry';
import type { DBWorkerRequest, DBWorkerResponse } from '../types/workers';

const CHUNK_VOLUME = 16 * 288 * 16; // 73728 elements (Y from -32 to 255)

const getIndex = (lx: number, ly: number, lz: number) => {
  const yOffset = ly - (-32);
  return yOffset * 256 + lz * 16 + lx;
};

const setBlock = (buffer: Uint32Array, index: number, textureId: number | string, health = 100, isHidden = 0, level = 0): void => {
  const t = typeof textureId === 'string' ? BlockIds[textureId] : textureId;
  const h = (health === Infinity || health >= 9999) ? 511 : Math.min(Math.max(health, 0), 510);
  buffer[index] =
    (t & 0xff) |
    ((h & 0x1ff) << 8) |
    ((level & 0xf) << 17) |
    ((isHidden ? 1 : 0) << 21);
};

const RLE_TEMP_BUFFER = new Uint32Array(CHUNK_VOLUME * 2);

const compressRLE = (bufferInput: ArrayBuffer | Uint32Array): Uint32Array => {
  const uint32Array = bufferInput instanceof Uint32Array ? bufferInput : new Uint32Array(bufferInput);
  let rleIdx = 0;
  let currentVal = uint32Array[0];
  let count = 1;
  for (let i = 1; i < uint32Array.length; i++) {
    if (uint32Array[i] === currentVal) {
      count++;
    } else {
      RLE_TEMP_BUFFER[rleIdx++] = count;
      RLE_TEMP_BUFFER[rleIdx++] = currentVal;
      currentVal = uint32Array[i];
      count = 1;
    }
  }
  RLE_TEMP_BUFFER[rleIdx++] = count;
  RLE_TEMP_BUFFER[rleIdx++] = currentVal;
  return new Uint32Array(RLE_TEMP_BUFFER.subarray(0, rleIdx));
};

const decompressRLE = (rleArray: ArrayBuffer | Uint32Array | { buffer: ArrayBuffer, byteOffset?: number, byteLength?: number }): Uint32Array => {
  let rleUint32: Uint32Array;
  if (rleArray instanceof Uint32Array) {
    rleUint32 = rleArray;
  } else if (rleArray && rleArray.buffer instanceof ArrayBuffer) {
    const buf = rleArray.buffer;
    const byteOffset = rleArray.byteOffset || 0;
    const byteLength = rleArray.byteLength || buf.byteLength;
    if (byteOffset % 4 === 0) {
      rleUint32 = new Uint32Array(buf, byteOffset, byteLength / 4);
    } else {
      const slicedBuf = buf.slice(byteOffset, byteOffset + byteLength);
      rleUint32 = new Uint32Array(slicedBuf);
    }
  } else if (rleArray instanceof ArrayBuffer) {
    rleUint32 = new Uint32Array(rleArray);
  } else {
    rleUint32 = new Uint32Array(rleArray);
  }
  const arr = new Uint32Array(CHUNK_VOLUME);
  let arrIdx = 0;
  for (let i = 0; i < rleUint32.length; i += 2) {
    const count = rleUint32[i];
    const val = rleUint32[i + 1];
    const end = Math.min(arrIdx + count, CHUNK_VOLUME);
    arr.fill(val, arrIdx, end);
    arrIdx = end;
  }
  return arr;
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const migrateLegacyChunk = (legacyData: any): { buffer: Uint32Array, isMigrated: boolean } | null => {
  const buffer = new Uint32Array(CHUNK_VOLUME);

  if (legacyData.buffer) {
    const buf = legacyData.buffer;
    const len = buf.byteLength || buf.buffer?.byteLength;
    if (len === 294912) {
      return legacyData;
    }
    if (len === 262144) {
      const uint32Array = buf.buffer ? new Uint32Array(buf.buffer) : new Uint32Array(buf);
      const newBuf = new Uint32Array(73728);
      newBuf.set(uint32Array, 8192); // Pad Y from 0 to 255 by shifting 32 * 256 blocks
      return { buffer: newBuf, isMigrated: true };
    }
    return null;
  }

  if (legacyData.blocks) {
    for (const key in legacyData.blocks) {
      const b = legacyData.blocks[key];
      if (b.pos) {
        const lx = ((b.pos[0] % 16) + 16) % 16;
        const lz = ((b.pos[2] % 16) + 16) % 16;
        const ly = Math.round(b.pos[1] - 0.5);

        let tex = b.texture;
        if (typeof tex === 'string') {
          tex = BlockIds[tex] || 1;
        }
        setBlock(buffer, getIndex(lx, ly, lz), tex, b.health || 100, b.isHidden ? 1 : 0, b.level || 0);
      }
    }
  } else if (legacyData.packedBuffer) {
    const pb = legacyData.packedBuffer;
    for (let i = 0; i < pb.length; i += 7) {
      const lx = ((pb[i] % 16) + 16) % 16;
      const ly = pb[i + 1];
      const lz = ((pb[i + 2] % 16) + 16) % 16;
      const isHidden = pb[i + 3];
      const tex = pb[i + 4];
      const health = pb[i + 5];
      const level = pb[i + 6];
      setBlock(buffer, getIndex(lx, ly, lz), tex, health, isHidden, level);
    }
  } else {
    return null;
  }

  return { buffer, isMigrated: true };
};

const walCache = new Map();
let walTimer = null;
let isFlushing = false;
let flushPromise = null;

const flushWAL = async () => {
  if (walCache.size === 0) return;
  if (isFlushing) {
    await flushPromise;
    if (walCache.size > 0) return flushWAL();
    return;
  }
  isFlushing = true;
  flushPromise = (async () => {
    const entries = Array.from(walCache.entries());
    try {
      await setMany(entries);
      entries.forEach(([key, data]) => {
        if (walCache.get(key) === data) {
          walCache.delete(key);
        }
      });
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) {
      console.error('Worker failed to flush WAL', err);
    } finally {
      isFlushing = false;
    }
  })();
  await flushPromise;
};

self.onmessage = async (e: MessageEvent<DBWorkerRequest>) => {
  const data = e.data;
  const id = data.id;
  const type = data.type;
  try {
    if (data.type === 'COMPRESS') {
      const rle = compressRLE(data.payload.buffer);
      self.postMessage({ id, result: rle }, [rle.buffer]);
    } else if (data.type === 'DECOMPRESS') {
      const uncompressed = decompressRLE(data.payload.rleBuffer);
      self.postMessage({ id, result: uncompressed }, [uncompressed.buffer]);
    } else if (data.type === 'SAVE_CHUNK') {
      const { chunkKey, slotPrefix, buffer, seed } = data.payload;
      const key = `${slotPrefix}_chunk_v14_${seed}_${chunkKey}`;
      const rleBuffer = compressRLE(buffer);
      walCache.set(key, { rleBuffer });

      if (!walTimer) {
        walTimer = setTimeout(() => {
          walTimer = null;
          flushWAL();
        }, 5000);
      }
      self.postMessage({ id, result: true });
    } else if (data.type === 'LOAD_CHUNK') {
      const { chunkKey, slotPrefix, seed } = data.payload;
      const key = `${slotPrefix}_chunk_v14_${seed}_${chunkKey}`;
      if (walCache.has(key)) {
        const walData = walCache.get(key);
        if (walData.rleBuffer) {
          const arr = decompressRLE(walData.rleBuffer);
          self.postMessage({ id, result: { buffer: arr, isMigrated: true } }, [arr.buffer]);
        } else {
          const arr = new Uint32Array(walData.buffer.slice(0));
          self.postMessage({ id, result: { buffer: arr, isMigrated: true } }, [arr.buffer]);
        }
      } else {
        const res = await get(key);
        if (res) {
          if (res.rleBuffer) {
            const arr = decompressRLE(res.rleBuffer);
            self.postMessage({ id, result: { buffer: arr, isMigrated: true } }, [arr.buffer]);
          } else {
            const migrated = migrateLegacyChunk(res);
            if (migrated && migrated.buffer) {
              const transfer = migrated.buffer instanceof ArrayBuffer
                ? migrated.buffer
                : migrated.buffer.buffer;
              if (migrated.buffer instanceof ArrayBuffer) {
                migrated.buffer = new Uint32Array(migrated.buffer);
              }
              self.postMessage({ id, result: migrated }, [transfer]);
            } else {
              self.postMessage({ id, result: migrated });
            }
          }
        } else {
          self.postMessage({ id, result: null });
        }
      }
    } else if (data.type === 'DELETE_CHUNK') {
      const { chunkKey, slotPrefix, seed } = data.payload;
      const key = `${slotPrefix}_chunk_v14_${seed}_${chunkKey}`;
      if (walCache.has(key)) walCache.delete(key);
      await del(key);
      self.postMessage({ id, result: true });
    } else if (data.type === 'CLEAR_DB') {
      const { slotId, isSlotPrefix } = data.payload;
      walCache.clear();
      if (walTimer) {
        clearTimeout(walTimer);
        walTimer = null;
      }
      const allKeys = await keys();
      for (const k of allKeys) {
        if (isSlotPrefix) {
          if (k.startsWith(`${slotId}_`) || k === `saveState_${slotId}`) {
            await del(k);
          }
        } else {
          if (k.startsWith(`${slotId}_`) || k === `saveState_slot${slotId}`) {
            await del(k);
          }
        }
      }
      self.postMessage({ id, result: true });
    } else if (data.type === 'FLUSH_WAL') {
      await flushWAL();
      self.postMessage({ id, result: true });
    }
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } catch (err: any) {
    self.postMessage({ id, error: err.message });
  }
};

